import{EVE_ROUTE_PREFIX}from"#protocol/routes.js";import{UnknownDevScheduleError,dispatchScheduleInDev}from"#internal/nitro/host/dispatch-schedule-in-dev.js";const DEV_DISPATCH_SCHEDULE_PATH_PATTERN=RegExp(`^${EVE_ROUTE_PREFIX.replace(/\//g,`\\/`)}\\/dev\\/schedules\\/([^/]+)$`);async function handleDevScheduleDispatchRequest(e,t){let n=new URL(t.url).pathname.match(DEV_DISPATCH_SCHEDULE_PATH_PATTERN)?.[1];if(typeof n!=`string`||n.length===0)return Response.json({error:`Missing schedule id.`},{status:400});let r;try{r=decodeURIComponent(n)}catch{return Response.json({error:`Schedule id is not a valid URI component.`},{status:400})}if(r.length===0)return Response.json({error:`Missing schedule id.`},{status:400});try{let t=await dispatchScheduleInDev({artifactsConfig:e,scheduleId:r});return Response.json({scheduleId:t.scheduleId,sessionIds:t.sessionIds})}catch(e){if(e instanceof UnknownDevScheduleError)return Response.json({error:e.message,availableScheduleIds:e.availableScheduleIds},{status:404});throw e}}export{handleDevScheduleDispatchRequest};